<script setup>
import { computed, onMounted, ref } from 'vue';
import SiteHeader from '../components/SiteHeader.vue';
import SiteFooter from '../components/SiteFooter.vue';
import Icon from '../components/Icon.vue';
import { listAffiliates } from '../services/affiliateApi.js';

const affiliates = ref([]); const loading = ref(true); const error = ref(''); const category = ref('ALL');
const categories = computed(() => ['ALL', ...new Set(affiliates.value.map(item => item.category).filter(Boolean))]);
const visible = computed(() => category.value === 'ALL' ? affiliates.value : affiliates.value.filter(item => item.category === category.value));
async function load() { loading.value = true; error.value = ''; try { affiliates.value = await listAffiliates(); } catch (failure) { error.value = failure.message || 'No se pudo cargar el directorio de aliados.'; } finally { loading.value = false; } }
onMounted(load);
</script>
<template>
  <div class="affiliate-page"><SiteHeader /><main class="affiliate-main"><section class="affiliate-hero"><h1>Aliados para cuidar <span>nuevas historias.</span></h1><p>Encuentra servicios y beneficios de organizaciones que acompañan a las familias después de la adopción.</p></section><section class="affiliate-toolbar" aria-label="Filtros del directorio"><label for="affiliate-category">Filtrar por categoría</label><select id="affiliate-category" v-model="category"><option v-for="item in categories" :key="item" :value="item">{{ item === 'ALL' ? 'Todas las categorías' : item }}</option></select></section><p v-if="loading" class="affiliate-state" role="status">Cargando aliados…</p><p v-else-if="error" class="affiliate-state affiliate-error" role="alert">{{ error }} <button type="button" @click="load">Reintentar</button></p><p v-else-if="!visible.length" class="affiliate-state">Aún no hay aliados publicados. Vuelve pronto para conocer los beneficios disponibles.</p><section v-else class="affiliate-grid" aria-label="Comercios aliados"><article v-for="item in visible" :key="item.id" class="affiliate-card"><div class="affiliate-card-heading"><span class="affiliate-icon"><Icon name="building-2" /></span><span class="affiliate-category">{{ item.category }}</span></div><h2>{{ item.name }}</h2><p v-if="item.description">{{ item.description }}</p><div v-if="item.location" class="affiliate-location"><Icon name="map-pin" />{{ item.location }}</div><div v-if="item.discountText || item.discountCode" class="affiliate-benefit"><Icon name="badge-check" /><span>{{ item.discountText || 'Beneficio disponible' }}<strong v-if="item.discountCode">Código: {{ item.discountCode }}</strong></span></div><a v-if="item.websiteUrl" class="affiliate-link" :href="item.websiteUrl" target="_blank" rel="noopener noreferrer">Visitar sitio <Icon name="arrow-up-right" /></a></article></section></main><SiteFooter /></div>
</template>
